21	// ── Dedup key ──
22	
23	pub fn compute_dedup_key(kind: &MemoryKind, statement: &str, entity_id: &str) -> String {
24	    let kind_str = serde_json::to_string(kind).unwrap_or_default();
25	    let mut hasher = Sha256::new();
26	    hasher.update(kind_str.as_bytes());
27	    hasher.update(b"\x00");
28	    hasher.update(statement.trim().to_lowercase().as_bytes());
29	    hasher.update(b"\x00");
30	    hasher.update(entity_id.as_bytes());
31	    format!("{:x}", hasher.finalize())
32	}
