34	// ── Extraction ──
35	
36	/// Deterministic extraction: one `outcome` MemoryItem per envelope.
37	/// Never fails — returns an empty vec on error.
38	pub fn extract_from_envelope(envelope: &SemanticEnvelope, now: &str) -> Vec<MemoryItem> {
39	    let statement = format!(
40	        "attempt {} was {}",
41	        envelope.capability_delta.attempted_capability,
42	        serde_json::to_string(&envelope.capability_delta.result)
43	            .unwrap_or_else(|_| "\"unknown\"".into())
44	            .trim_matches('"')
45	    );
46	    let statement: String = statement.chars().take(MAX_STATEMENT_LEN).collect();
47	    let dedup_key = compute_dedup_key(
48	        &MemoryKind::Outcome,
49	        &statement,
50	        &envelope.attribution.entity_id,
51	    );
52	    let memory_id = match ids::random_id("mem") {
53	        Ok(id) => id,
54	        Err(_) => return vec![],
55	    };
56	    vec![MemoryItem {
57	        version: RECORD_VERSION.into(),
58	        memory_id,
59	        kind: MemoryKind::Outcome,
60	        statement,
61	        attribution: Attribution {
62	            entity_id: envelope.attribution.entity_id.clone(),
63	            process_id: envelope.attribution.process_id.clone(),
64	            session_id: envelope.attribution.session_id.clone(),
65	        },
66	        provenance: MemoryItemProvenance {
67	            run_ids: vec![envelope.run_id.clone()],
68	            evidence_refs: envelope.evidence_refs.clone(),
69	        },
70	        dedup_key,
71	        created_at: now.to_string(),
72	        last_confirmed_at: now.to_string(),
73	    }]
74	}
