76	// ── items.jsonl store (append-only; dedup at read) ──
77	
78	pub fn append_memory_items(path: &Path, items: &[MemoryItem]) -> Result<(), ForgeError> {
79	    if let Some(parent) = path.parent() {
80	        std::fs::create_dir_all(parent).map_err(|e| ForgeError::io("create memory dir", e))?;
81	    }
82	    let mut file = OpenOptions::new()
83	        .create(true)
84	        .append(true)
85	        .open(path)
86	        .map_err(|e| ForgeError::io("open memory items", e))?;
87	    for item in items {
88	        let mut encoded = serde_json::to_vec(item)?;
89	        encoded.push(b'\n');
90	        file.write_all(&encoded)
91	            .map_err(|e| ForgeError::io("append memory item", e))?;
92	    }
93	    file.flush()
94	        .map_err(|e| ForgeError::io("flush memory items", e))
95	}
96	
97	pub fn load_memory_items(path: &Path) -> Result<Vec<MemoryItem>, ForgeError> {
98	    let file = File::open(path).map_err(|e| ForgeError::io("open memory items", e))?;
99	    let mut items = Vec::new();
100	    for line in BufReader::new(file).lines() {
101	        let line = line.map_err(|e| ForgeError::io("read memory items", e))?;
102	        match serde_json::from_str::<MemoryItem>(&line) {
103	            Ok(item) => items.push(item),
104	            Err(_) => { /* skip malformed */ }
105	        }
106	    }
107	    Ok(deduplicate(items))
108	}
