110	/// Merge items with the same dedup_key: union run_ids/evidence_refs,
111	/// take earliest created_at, latest last_confirmed_at.
112	fn deduplicate(items: Vec<MemoryItem>) -> Vec<MemoryItem> {
113	    let mut by_key: HashMap<String, MemoryItem> = HashMap::new();
114	    for item in items {
115	        by_key
116	            .entry(item.dedup_key.clone())
117	            .and_modify(|existing| {
118	                for rid in &item.provenance.run_ids {
119	                    if !existing.provenance.run_ids.contains(rid) {
120	                        existing.provenance.run_ids.push(rid.clone());
121	                    }
122	                }
123	                for eid in &item.provenance.evidence_refs {
124	                    if !existing.provenance.evidence_refs.contains(eid) {
125	                        existing.provenance.evidence_refs.push(eid.clone());
126	                    }
127	                }
128	                if item.last_confirmed_at > existing.last_confirmed_at {
129	                    existing.last_confirmed_at = item.last_confirmed_at.clone();
130	                }
131	                if item.created_at < existing.created_at {
132	                    existing.created_at = item.created_at.clone();
133	                }
134	            })
135	            .or_insert(item);
136	    }
137	    let mut result: Vec<MemoryItem> = by_key.into_values().collect();
138	    result.sort_by(|a, b| b.last_confirmed_at.cmp(&a.last_confirmed_at));
139	    result
140	}
