142	// ── Recall ──
143	
144	pub struct MemoryRecallQuery<'a> {
145	    pub query: &'a str,
146	    pub entity_id: Option<&'a str>,
147	    pub process_id: Option<&'a str>,
148	    pub kinds: Option<&'a [MemoryKind]>,
149	    pub limit: usize,
150	}
151	
152	/// Linear scan of items.jsonl. The source of truth for recall.
153	pub fn recall_memory(
154	    path: &Path,
155	    query: MemoryRecallQuery<'_>,
156	) -> Result<Vec<MemoryItem>, ForgeError> {
157	    let items = load_memory_items(path)?;
158	    let needle = query.query.to_lowercase();
159	    let limit = query.limit.min(MAX_RECALL_LIMIT);
160	    let mut results: Vec<MemoryItem> = items
161	        .into_iter()
162	        .filter(|item| {
163	            item.statement.to_lowercase().contains(&needle)
164	                && query
165	                    .entity_id
166	                    .is_none_or(|e| item.attribution.entity_id == e)
167	                && query
168	                    .process_id
169	                    .is_none_or(|p| item.attribution.process_id == p)
170	                && query.kinds.is_none_or(|kinds| kinds.contains(&item.kind))
171	        })
172	        .take(limit)
173	        .collect();
174	    // Return most-recently-confirmed first.
175	    results.sort_by(|a, b| b.last_confirmed_at.cmp(&a.last_confirmed_at));
176	    Ok(results)
177	}
