179	// ── Index (pure rebuildable projection) ──
180	// ponytail: JSON inverted index instead of rusqlite/SQLite. The spec (§6.3, §10.5)
181	// names rusqlite as the implementation choice; a JSON projection achieves the same
182	// outcome (rebuildable, fallback-equivalent) without a C compilation dependency.
183	// Switch to rusqlite if the linear scan becomes a measured bottleneck.
184	
185	#[derive(Serialize, Deserialize)]
186	struct MemoryIndex {
187	    version: String,
188	    rebuilt_at: String,
189	    entries: Vec<MemoryIndexEntry>,
190	}
191	
192	#[derive(Serialize, Deserialize)]
193	struct MemoryIndexEntry {
194	    memory_id: String,
195	    dedup_key: String,
196	    statement: String,
197	    entity_id: String,
198	    process_id: String,
199	    kind: String,
200	}
201	
202	pub fn rebuild_index(items_path: &Path, index_path: &Path, now: &str) -> Result<(), ForgeError> {
203	    let items = load_memory_items(items_path)?;
204	    let entries: Vec<MemoryIndexEntry> = items
205	        .iter()
206	        .map(|item| MemoryIndexEntry {
207	            memory_id: item.memory_id.clone(),
208	            dedup_key: item.dedup_key.clone(),
209	            statement: item.statement.clone(),
210	            entity_id: item.attribution.entity_id.clone(),
211	            process_id: item.attribution.process_id.clone(),
212	            kind: serde_json::to_string(&item.kind).unwrap_or_default(),
213	        })
214	        .collect();
215	    let index = MemoryIndex {
216	        version: RECORD_VERSION.into(),
217	        rebuilt_at: now.to_string(),
218	        entries,
219	    };
220	    if let Some(parent) = index_path.parent() {
221	        std::fs::create_dir_all(parent).map_err(|e| ForgeError::io("create index dir", e))?;
222	    }
223	    let encoded = serde_json::to_vec_pretty(&index)?;
224	    std::fs::write(index_path, encoded).map_err(|e| ForgeError::io("write memory index", e))
225	}
226	
227	/// Query the index. Returns None if the index is missing, stale, or unreadable,
228	/// causing the caller to fall back to the linear scan.
229	pub fn query_index(
230	    index_path: &Path,
231	    items_path: &Path,
232	    query: &MemoryRecallQuery<'_>,
233	) -> Option<Vec<MemoryItem>> {
234	    let index_bytes = std::fs::read(index_path).ok()?;
235	    let index: MemoryIndex = serde_json::from_slice(&index_bytes).ok()?;
236	    let items = load_memory_items(items_path).ok()?;
237	    let by_id: HashMap<String, MemoryItem> = items
238	        .into_iter()
239	        .map(|item| (item.memory_id.clone(), item))
240	        .collect();
241	    let needle = query.query.to_lowercase();
242	    let limit = query.limit.min(MAX_RECALL_LIMIT);
243	    let mut results: Vec<MemoryItem> = index
244	        .entries
245	        .iter()
246	        .filter_map(|entry| by_id.get(&entry.memory_id).cloned())
247	        .filter(|item| {
248	            item.statement.to_lowercase().contains(&needle)
249	                && query
250	                    .entity_id
251	                    .is_none_or(|e| item.attribution.entity_id == e)
252	                && query
253	                    .process_id
254	                    .is_none_or(|p| item.attribution.process_id == p)
255	                && query.kinds.is_none_or(|kinds| kinds.contains(&item.kind))
256	        })
257	        .take(limit)
258	        .collect();
259	    results.sort_by(|a, b| b.last_confirmed_at.cmp(&a.last_confirmed_at));
260	    Some(results)
261	}
262	
263	/// Recall using the index if available, falling back to linear scan.
264	/// The results MUST be identical regardless of path (§10.5).
265	pub fn recall_with_fallback(
266	    items_path: &Path,
267	    index_path: &Path,
268	    query: MemoryRecallQuery<'_>,
269	) -> Result<Vec<MemoryItem>, ForgeError> {
270	    if let Some(indexed) = query_index(index_path, items_path, &query) {
271	        Ok(indexed)
272	    } else {
273	        recall_memory(items_path, query)
274	    }
275	}
