50	// ── 1. Two-entity extraction produces deduplicated, provenance-linked items ──
51	
52	#[test]
53	fn two_entity_extraction_deduplicates_and_links_provenance() {
54	    let dir = TempDir::new().unwrap();
55	
56	    // Entity A runs the same capability twice with the same result.
57	    let env1 = make_envelope("run_001", "entity_a", "cap_x", SettlementStatus::Accepted);
58	    let env2 = make_envelope("run_002", "entity_a", "cap_x", SettlementStatus::Accepted);
59	    // Entity B runs the same capability with the same result.
60	    let env3 = make_envelope("run_003", "entity_b", "cap_x", SettlementStatus::Accepted);
61	
62	    let items1 = extract_from_envelope(&env1, "2026-07-14T00:00:00Z");
63	    let items2 = extract_from_envelope(&env2, "2026-07-14T01:00:00Z");
64	    let items3 = extract_from_envelope(&env3, "2026-07-14T02:00:00Z");
65	
66	    write_items(&dir, &items1);
67	    write_items(&dir, &items2);
68	    write_items(&dir, &items3);
69	
70	    let loaded =
71	        sea_forge_capability::memory::load_memory_items(&dir.path().join("memory/items.jsonl"))
72	            .unwrap();
73	
74	    // Entity A items dedup to one item (same dedup_key), entity B is a separate item.
75	    assert_eq!(
76	        loaded.len(),
77	        2,
78	        "expected 2 items after dedup (one per entity)"
79	    );
80	
81	    let entity_a_item = loaded
82	        .iter()
83	        .find(|i| i.attribution.entity_id == "entity_a")
84	        .expect("entity_a item exists");
85	    assert_eq!(entity_a_item.kind, MemoryKind::Outcome);
86	    assert_eq!(
87	        entity_a_item.provenance.run_ids,
88	        vec!["run_001".to_string(), "run_002".to_string()],
89	        "provenance should merge run_ids from both extractions"
90	    );
91	    assert_eq!(
92	        entity_a_item.last_confirmed_at, "2026-07-14T01:00:00Z",
93	        "last_confirmed_at should be the latest"
94	    );
95	    assert_eq!(
96	        entity_a_item.created_at, "2026-07-14T00:00:00Z",
97	        "created_at should be the earliest"
98	    );
99	
100	    let entity_b_item = loaded
101	        .iter()
102	        .find(|i| i.attribution.entity_id == "entity_b")
103	        .expect("entity_b item exists");
104	    assert_eq!(
105	        entity_b_item.provenance.run_ids,
106	        vec!["run_003".to_string()]
107	    );
108	}
