151	// ── 4. Index-delete ⇒ identical recall results via fallback scan ──
152	
153	#[test]
154	fn index_delete_yields_identical_recall_via_fallback() {
155	    let dir = TempDir::new().unwrap();
156	
157	    for i in 0..5 {
158	        let entity = if i % 2 == 0 { "entity_a" } else { "entity_b" };
159	        let cap = format!("cap_{i}");
160	        let result = if i % 3 == 0 {
161	            SettlementStatus::Rejected
162	        } else {
163	            SettlementStatus::Accepted
164	        };
165	        let env = make_envelope(&format!("run_{i:03}"), entity, &cap, result);
166	        let items = extract_from_envelope(&env, &format!("2026-07-14T0{i}:00:00Z"));
167	        write_items(&dir, &items);
168	    }
169	
170	    let items_path = dir.path().join("memory/items.jsonl");
171	    let index_path = dir.path().join("memory/index.json");
172	
173	    // Build the index.
174	    rebuild_index(&items_path, &index_path, "2026-07-14T00:00:00Z").unwrap();
175	    assert!(index_path.exists(), "index should exist after rebuild");
176	
177	    // Query via index.
178	    let indexed_results = recall_with_fallback(
179	        &items_path,
180	        &index_path,
181	        MemoryRecallQuery {
182	            query: "attempt",
183	            entity_id: None,
184	            process_id: None,
185	            kinds: None,
186	            limit: 50,
187	        },
188	    )
189	    .unwrap();
190	
191	    // Delete the index → fallback scan.
192	    std::fs::remove_file(&index_path).unwrap();
193	    assert!(!index_path.exists(), "index deleted");
194	
195	    let fallback_results = recall_with_fallback(
196	        &items_path,
197	        &index_path,
198	        MemoryRecallQuery {
199	            query: "attempt",
200	            entity_id: None,
201	            process_id: None,
202	            kinds: None,
203	            limit: 50,
204	        },
205	    )
206	    .unwrap();
207	
208	    assert_eq!(
209	        indexed_results.len(),
210	        fallback_results.len(),
211	        "index and fallback return same count"
212	    );
213	    for (indexed, fallback) in indexed_results.iter().zip(fallback_results.iter()) {
214	        assert_eq!(
215	            indexed.memory_id, fallback.memory_id,
216	            "same memory_id ordering"
217	        );
218	        assert_eq!(indexed.statement, fallback.statement, "same statement");
219	        assert_eq!(indexed.dedup_key, fallback.dedup_key, "same dedup_key");
220	    }
221	}
