7	pub struct RecallOptions<'a> {
8	    pub root: &'a Path,
9	    pub policy: Option<&'a Path>,
10	    pub actor_id: &'a str,
11	    pub query: &'a str,
12	    pub entity: Option<&'a str>,
13	    pub process: Option<&'a str>,
14	    pub result: Option<SettlementStatus>,
15	    pub kind: Option<MemoryKind>,
16	    pub limit: usize,
17	}
18	
19	pub fn execute(options: RecallOptions<'_>) -> Result<u8, ForgeError> {
20	    let RecallOptions {
21	        root,
22	        policy,
23	        actor_id,
24	        query,
25	        entity,
26	        process,
27	        result,
28	        kind,
29	        limit,
30	    } = options;
31	
32	    // Memory-item recall mode (M4b): search memory/items.jsonl when --kind is set.
33	    if let Some(memory_kind) = kind {
34	        return execute_memory_recall(root, policy, actor_id, query, entity, memory_kind, limit);
35	    }
36	
37	    let capability_path = root.join("capabilities.jsonl");
38	    let policy = super::mediated::policy_path(root, policy);
39	    super::mediated::authorize_read(
40	        root,
41	        &policy,
42	        actor_id,
43	        &AuthorityAction::Reserved {
44	            resource_type: "recall_memory".into(),
45	            resource_id: "capabilities".into(),
46	            parameters: serde_json::json!({"limit": limit}),
47	        },
48	    )?;
49	    if !capability_path.exists() {
50	        std::fs::File::open(&capability_path)
51	            .map_err(|error| ForgeError::io("open capability memory", error))?;
52	    }
53	    let (matches, malformed) = capability::recall(
54	        &capability_path,
55	        RecallQuery {
56	            query,
57	            entity,
58	            process,
59	            result,
60	            limit,
61	        },
62	    )?;
63	    if malformed > 0 {
64	        tracing::warn!(
65	            event = "recall_malformed_lines",
66	            run_id = "none",
67	            component = "sea-forge-cli::recall",
68	            error_class = "capability_parse_error",
69	            malformed_lines = malformed
70	        );
71	    }
72	    for envelope in &matches {
73	        let mut value = serde_json::to_value(envelope)?;
74	        if let Some(object) = value.as_object_mut() {
75	            let assurance = super::mediated::record_assurance(
76	                root,
77	                &policy,
78	                actor_id,
79	                "capability_envelope",
80	                envelope,
81	            )?;
82	            object.insert("assurance".into(), assurance.into());
83	        }
84	        println!("{}", serde_json::to_string(&value)?);
85	    }
86	    Ok(if matches.is_empty() { 3 } else { 0 })
87	}
