89	fn execute_memory_recall(
90	    root: &Path,
91	    policy: Option<&Path>,
92	    actor_id: &str,
93	    query: &str,
94	    entity: Option<&str>,
95	    kind: MemoryKind,
96	    limit: usize,
97	) -> Result<u8, ForgeError> {
98	    let policy_path = super::mediated::policy_path(root, policy);
99	    super::mediated::authorize_read(
100	        root,
101	        &policy_path,
102	        actor_id,
103	        &AuthorityAction::Reserved {
104	            resource_type: "recall_memory".into(),
105	            resource_id: "memory".into(),
106	            parameters: serde_json::json!({"kind": kind, "limit": limit}),
107	        },
108	    )?;
109	    let items_path = root.join("memory/items.jsonl");
110	    let index_path = root.join("memory/index.json");
111	    let kind_slice = [kind];
112	    let kinds = Some(kind_slice.as_slice());
113	    let results = capability::memory::recall_with_fallback(
114	        &items_path,
115	        &index_path,
116	        capability::memory::MemoryRecallQuery {
117	            query,
118	            entity_id: entity,
119	            process_id: None,
120	            kinds,
121	            limit,
122	        },
123	    )?;
124	    for item in &results {
125	        println!("{}", serde_json::to_string(item)?);
126	    }
127	    Ok(if results.is_empty() { 3 } else { 0 })
128	}
