130	fn authorize_with_bundle_callback<T>(
131	    root: &Path,
132	    actor_id: &str,
133	    action: &AuthorityAction,
134	    bundle: AuthorityPolicyBundle,
135	    context: AuthorityContext<'_>,
136	    require_side_effect_assurance: bool,
137	    callback: impl FnOnce(ActionGrant, AuthorityDecision, CommittedRecordRef) -> Result<T, ForgeError>,
138	) -> Result<T, ForgeError> {
139	    let stream = LedgerStream::open(root, "authority-reads", actor_id)?;
140	    stream.commit_typed("authority_policy", vec![], &bundle, vec![])?;
141	    let integrity = bundle.integrity_ledger.clone();
142	    let binding = bundle.resolve_identity(actor_id, ActorRole::Operator);
143	    let domainforge_model = bundle.load_domainforge_model()?;
144	    let domainforge_candidate = domainforge_model
145	        .as_ref()
146	        .map(|model| {
147	            sea_forge_authority::DomainForgeCandidate::evaluate(
148	                model,
149	                action,
150	                vec![format!(
151	                    "domain-model:{}",
152	                    model.model_ref.semantic_model_sha256
153	                )],
154	            )
155	        })
156	        .transpose()?;
157	    let engine = PolicyAuthorityEngine::new(bundle)?;
158	    engine.load_opaque_constraints(crate::pipeline::load_opaque_constraints(root)?)?;
159	    let evidence = stream.commit_typed(
160	        "authority_evidence",
161	        vec![actor_id.into()],
162	        &serde_json::json!({"kind": "ingress_authority_request", "action": action}),
163	        vec![],
164	    )?;
165	    let actor = Actor {
166	        actor_id: actor_id.into(),
167	        role: ActorRole::Operator,
168	    };
169	    let decision = engine.evaluate(AuthorityEvaluation {
170	        actor: &actor,
171	        binding,
172	        run_id: context.run_id,
173	        case_id: context.case_id,
174	        plan_item_id: context.plan_item_id,
175	        sequence: context.sequence,
176	        action,
177	        workspace_root: root,
178	        evidence_refs: vec![evidence.entry_ulid().into()],
179	        artifacts_root: None,
180	        timeout_secs: None,
181	        env_keys: Default::default(),
182	        domainforge_candidate: domainforge_candidate.as_ref(),
183	        environment: None,
184	    })?;
185	    let committed = stream.commit_typed("authority_decision", vec![], &decision, vec![])?;
186	    crate::pipeline::rebuild_authority_mirrors(root, &stream, &committed)?;
187	    let assurance = if require_side_effect_assurance && integrity.required_for_side_effects {
188	        let key_dir = integrity.signing_key_dir.as_deref().ok_or_else(|| {
189	            ForgeError::Internal("ledger_integrity_error: signing_key_dir is required".into())
190	        })?;
191	        Some(
192	            LedgerManager::new(root)?.create_pre_action_assurance(
193	                key_dir,
194	                &integrity.signing_key_id,
195	                actor_id,
196	                &integrity
197	                    .witnesses
198	                    .iter()
199	                    .map(|witness| {
200	                        (
201	                            witness.witness_id.clone(),
202	                            witness.key_dir.clone(),
203	                            witness.key_id.clone(),
204	                        )
205	                    })
206	                    .collect::<Vec<_>>(),
207	                integrity.min_witnesses,
208	                &[&committed],
209	            )?,
210	        )
211	    } else {
212	        None
213	    };
214	    let grant = engine.grant(&decision, &committed, action, assurance.as_ref())?;
215	    callback(grant, decision, committed)
216	}
