224	fn verified_assurance(
225	    root: &Path,
226	    policy_path: &Path,
227	    actor_id: &str,
228	) -> Result<(String, Option<String>), ForgeError> {
229	    let manager = LedgerManager::new(root)?;
230	    for stream_id in manager.list_stream_ids()? {
231	        manager.open_stream(&stream_id, "assurance")?.verify()?;
232	    }
233	    if !root.join("ledgers/global-checkpoints.jsonl").is_file() {
234	        return Ok(("local_tamper_evident".into(), None));
235	    }
236	    // Migrated roots are historical snapshots; their assurance level is fixed at legacy.
237	    if root.join("migration.json").is_file() {
238	        return Ok(("legacy_digest_only".into(), None));
239	    }
240	    let policy = AuthorityPolicyBundle::load(policy_path)?;
241	    let key_dir = policy
242	        .integrity_ledger
243	        .signing_key_dir
244	        .as_deref()
245	        .ok_or_else(|| ForgeError::Internal("ledger_integrity_error: signer unavailable".into()))?;
246	    let verifying_key = read_verifying_key(key_dir, &policy.integrity_ledger.signing_key_id)?;
247	    manager.verify_global_checkpoints(&verifying_key)?;
248	    if policy.integrity_ledger.min_witnesses == 0 {
249	        let checkpoint_hash = manager
250	            .read_global_checkpoints()?
251	            .last()
252	            .map(|checkpoint| checkpoint.global_checkpoint_hash.clone());
253	        return Ok(("checkpoint_signed".into(), checkpoint_hash));
254	    }
255	    let checkpoints = manager.read_global_checkpoints()?;
256	    let checkpoint = checkpoints
257	        .get(checkpoints.len().saturating_sub(2))
258	        .ok_or_else(|| {
259	            ForgeError::Internal("ledger_integrity_error: witnessed checkpoint missing".into())
260	        })?;
261	    let witness_keys = policy
262	        .integrity_ledger
263	        .witnesses
264	        .iter()
265	        .map(|witness| {
266	            Ok((
267	                witness.witness_id.clone(),
268	                read_verifying_key(&witness.key_dir, &witness.key_id)?,
269	            ))
270	        })
271	        .collect::<Result<Vec<_>, ForgeError>>()?;
272	    let witness_assurance = manager.verify_witness_receipts(
273	        &checkpoint.global_checkpoint_hash,
274	        &witness_keys,
275	        actor_id,
276	        policy.integrity_ledger.min_witnesses,
277	    )?;
278	    if witness_assurance != sea_forge_ledger::AssuranceLevel::ExternallyVerified {
279	        return Err(ForgeError::Internal(
280	            "ledger_integrity_error: insufficient independent witnesses".into(),
281	        ));
282	    }
283	    Ok((
284	        "externally_verified".into(),
285	        Some(checkpoint.global_checkpoint_hash.clone()),
286	    ))
287	}
288	
289	pub fn assurance(root: &Path, policy_path: &Path, actor_id: &str) -> Result<String, ForgeError> {
290	    verified_assurance(root, policy_path, actor_id).map(|(label, _)| label)
291	}
292	
293	pub fn record_assurance<T: serde::Serialize>(
294	    root: &Path,
295	    policy_path: &Path,
296	    actor_id: &str,
297	    record_kind: &str,
298	    record: &T,
299	) -> Result<String, ForgeError> {
300	    let (label, checkpoint_hash) = verified_assurance(root, policy_path, actor_id)?;
301	    let Some(checkpoint_hash) = checkpoint_hash else {
302	        return Ok("legacy_digest_only".into());
303	    };
304	    let manager = LedgerManager::new(root)?;
305	    if manager.global_checkpoint_covers_record(&checkpoint_hash, record_kind, record)? {
306	        Ok(label)
307	    } else {
308	        Ok("legacy_digest_only".into())
309	    }
310	}
