    run_intent(&root, &policy, "team_b", "agent_2");

    let without_index = stdout_lines(&recall_memory(
        &root,
        &policy,
        "operator_local",
        None,
        None,
    ));
    assert!(!without_index.is_empty());

    let rebuild = Command::new(env!("CARGO_BIN_EXE_sea-forge"))
