        items
            .iter()
            .map(|i| i["memory_id"].as_str().unwrap().to_string())
            .collect()
    };
    assert_eq!(
        ids(&without_index),
        ids(&with_index),
        "indexed and fallback CLI recall must return identical ordered IDs"
    );
